"""Small standard-library client for OpenAI's Responses API.

The client defaults to ``store=False`` so private prompts and responses are not
stored by OpenAI for later use. Keep prompts out of logs and exception messages
in calling code as well.
"""

from __future__ import annotations

import json
import os
import urllib.error
import urllib.request
from dataclasses import dataclass
from typing import Any, Mapping


API_URL = "https://api.openai.com/v1/responses"
DEFAULT_MODEL = "gpt-4.1-mini"


class OpenAIClientError(RuntimeError):
    """Raised when the Responses API request fails."""

    def __init__(self, message: str, *, status: int | None = None, body: str | None = None):
        super().__init__(message)
        self.status = status
        self.body = body


@dataclass(frozen=True)
class OpenAIClient:
    """Minimal Responses API client using only Python's standard library."""

    api_key: str | None = None
    model: str = DEFAULT_MODEL
    base_url: str = API_URL
    timeout: float = 60.0

    def __post_init__(self) -> None:
        if self.api_key is None:
            key = os.environ.get("OPENAI_API_KEY")
            if not key:
                raise OpenAIClientError("Set OPENAI_API_KEY or pass api_key explicitly.")
            object.__setattr__(self, "api_key", key)

    def create_response(
        self,
        prompt: str,
        *,
        model: str | None = None,
        instructions: str | None = None,
        max_output_tokens: int | None = None,
        temperature: float | None = None,
        store: bool = False,
        extra: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Send a private text prompt and return the raw Responses API JSON."""

        payload: dict[str, Any] = {
            "model": model or self.model,
            "input": prompt,
            "store": store,
        }
        if instructions is not None:
            payload["instructions"] = instructions
        if max_output_tokens is not None:
            payload["max_output_tokens"] = max_output_tokens
        if temperature is not None:
            payload["temperature"] = temperature
        if extra:
            payload.update(extra)

        data = json.dumps(payload).encode("utf-8")
        request = urllib.request.Request(
            self.base_url,
            data=data,
            method="POST",
            headers={
                "Authorization": f"Bearer {self.api_key}",
                "Content-Type": "application/json",
                "Accept": "application/json",
            },
        )

        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                return json.loads(response.read().decode("utf-8"))
        except urllib.error.HTTPError as exc:
            body = exc.read().decode("utf-8", errors="replace")
            raise OpenAIClientError(
                f"OpenAI Responses API request failed with HTTP {exc.code}.",
                status=exc.code,
                body=body,
            ) from exc
        except urllib.error.URLError as exc:
            raise OpenAIClientError(f"OpenAI Responses API request failed: {exc.reason}") from exc
        except json.JSONDecodeError as exc:
            raise OpenAIClientError("OpenAI Responses API returned invalid JSON.") from exc

    def prompt_text(self, prompt: str, **kwargs: Any) -> str:
        """Send a prompt and return the concatenated text output."""

        response = self.create_response(prompt, **kwargs)
        return extract_text(response)


def extract_text(response: Mapping[str, Any]) -> str:
    """Extract text content from a Responses API response object."""

    if isinstance(response.get("output_text"), str):
        return response["output_text"]

    chunks: list[str] = []
    for item in response.get("output", []):
        if not isinstance(item, Mapping):
            continue
        for content in item.get("content", []):
            if not isinstance(content, Mapping):
                continue
            text = content.get("text")
            if isinstance(text, str):
                chunks.append(text)
    return "".join(chunks)


def send_private_prompt(prompt: str, **kwargs: Any) -> str:
    """Convenience helper that sends a private prompt using OPENAI_API_KEY."""

    return OpenAIClient().prompt_text(prompt, **kwargs)


__all__ = [
    "DEFAULT_MODEL",
    "OpenAIClient",
    "OpenAIClientError",
    "extract_text",
    "send_private_prompt",
]
